 r['rows'][i]['final']=r['rows'][i]['final'].replace(old,new)
 r['rows'][i]['scan_shows']+=' Blind audit: the first surviving loop also admits qui; the following crossed outlines allow est or définit as tentative phrase alternatives, but do not settle the obscured original word. Retain the first reading with these explicit alternatives.'
